 static void Main(){var a=Record("ffffffffffffffffffffffffffffffff");var b=Record("11111111111111111111111111111111");var values=new Dictionary<string,RebirthStationDiscoveryAdmissionBinding>{{a.JobId,a},{b.JobId,b}};var section=RebirthStationDiscoveryAdmissionPersistence.Write(values,owner,creation);Check((string)section.Elements().First().Attribute("job")==b.JobId,"ordinal writer");Check(RebirthStationDiscoveryAdmissionPersistence.TryRead(new XElement("progression",section),owner,creation,out var read,out _)&&read.Count==2&&XNode.DeepEquals(section,RebirthStationDiscoveryAdmissionPersistence.Write(read,owner,creation)),"actual binding section roundtrip");Check(RebirthStationDiscoveryAdmissionPersistence.TryRead(new XElement("progression"),owner,creation,out read,out _)&&read.Count==0,"old absent section empty");
